using ItSupport.Api.Domain;
using Microsoft.EntityFrameworkCore;
namespace ItSupport.Api.Infrastructure;
public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
 public DbSet<Ticket> Tickets => Set<Ticket>(); public DbSet<TicketComment> TicketComments => Set<TicketComment>(); public DbSet<TicketHistory> TicketHistory => Set<TicketHistory>(); public DbSet<TicketAttachment> TicketAttachments => Set<TicketAttachment>(); public DbSet<AssignmentGroup> AssignmentGroups => Set<AssignmentGroup>(); public DbSet<Category> Categories => Set<Category>(); public DbSet<ServiceItem> Services => Set<ServiceItem>(); public DbSet<PriorityOption> Priorities => Set<PriorityOption>(); public DbSet<StatusOption> Statuses => Set<StatusOption>(); public DbSet<RoutingRule> RoutingRules => Set<RoutingRule>(); public DbSet<KnowledgeArticle> KnowledgeArticles => Set<KnowledgeArticle>(); public DbSet<ChatSession> ChatSessions => Set<ChatSession>(); public DbSet<ChatMessage> ChatMessages => Set<ChatMessage>(); public DbSet<AuditLog> AuditLogs => Set<AuditLog>();
 protected override void OnModelCreating(ModelBuilder b) { b.Entity<Ticket>().HasIndex(x => x.Number).IsUnique(); b.Entity<ChatSession>().HasIndex(x => x.PublicId).IsUnique(); b.Entity<Ticket>().HasMany(x => x.Comments).WithOne().HasForeignKey(x => x.TicketId).OnDelete(DeleteBehavior.Cascade); b.Entity<Ticket>().HasMany(x => x.History).WithOne().HasForeignKey(x => x.TicketId).OnDelete(DeleteBehavior.Cascade); b.Entity<Ticket>().HasMany(x => x.Attachments).WithOne().HasForeignKey(x => x.TicketId).OnDelete(DeleteBehavior.Cascade); b.Entity<ChatSession>().HasMany(x => x.Messages).WithOne().HasForeignKey(x => x.ChatSessionId).OnDelete(DeleteBehavior.Cascade); }
}
